package com.dronefleet.ui;
import com.dronefleet.config.*;import com.dronefleet.event.*;import com.dronefleet.repository.*;import com.dronefleet.service.*;import com.dronefleet.strategy.*;
public final class AppContextHolder{private static AppContext ctx;public static synchronized AppContext get(){if(ctx==null)ctx=new AppContext();return ctx;}public static synchronized void shutdown(){if(ctx!=null){ctx.delivery.shutdown();ctx.fleet.shutdown();}}public static final class AppContext{public final AppConfig cfg=new AppConfig();public final Database db=new Database(cfg.databaseUrl());public final EventBus bus=new EventBus();public final AuditRepository auditRepo;public final AuditRepositoryAdapter audit;public final FleetService fleet;public final DeliveryService delivery;public final AnalyticsService analytics;public final ExportService export=new ExportService();AppContext(){db.initialize();var dr=new DroneRepository(db);var dl=new DeliveryRepository(db);auditRepo=new AuditRepository(db);audit=new AuditRepositoryAdapter(auditRepo);fleet=new FleetService(dr,auditRepo,cfg,dl);delivery=new DeliveryService(dr,dl,auditRepo,new BestFitAssignmentStrategy(),bus,cfg);fleet.recoverAfterRestart(dl.recoverInterruptedDeliveries());analytics=new AnalyticsService(fleet,delivery);}}
}
